parameters.query:
// Every node with a heartbeat in the last 30 days (the retention), all
// selected.
let machines = "/providers/microsoft.hybridcompute/machines/";
let node_of = (id: string) { tolower(extract(@"(?i)/machines/([^/]+)$", 1, id)) };
union isfuzzy=true
    (Heartbeat | where _ResourceId has machines | project Node = node_of(_ResourceId)),
    (datatable(Node: string)[])
| distinct value = Node
| extend label = value, selected = true
| order by value asc

content.query:
// One row per node: its last heartbeat and counters, and CPU, memory and
// free space on / over the 5 minutes before its last counters. Silent:
// no heartbeat for more than 5 minutes. Over the last 30 days, as the
// picker, not the chart range, so a node silent for longer than the range
// still shows.
let machines = "/providers/microsoft.hybridcompute/machines/";
let node_of = (id: string) { tolower(extract(@"(?i)/machines/([^/]+)$", 1, id)) };
let beats = union isfuzzy=true
    (Heartbeat | where _ResourceId has machines | project TimeGenerated, Node = node_of(_ResourceId), Version),
    (datatable(TimeGenerated: datetime, Node: string, Version: string)[])
    | where Node in ({Nodes})
    | summarize arg_max(TimeGenerated, Version) by Node
    | project Node, LastHeartbeat = TimeGenerated, Agent = Version;
let perf = union isfuzzy=true
    (Perf
    | where _ResourceId has machines
    | project TimeGenerated, Node = node_of(_ResourceId), ObjectName, CounterName, InstanceName, CounterValue),
    (datatable(TimeGenerated: datetime, Node: string, ObjectName: string, CounterName: string, InstanceName: string,
        CounterValue: real)[])
    | where Node in ({Nodes});
let last_perf = perf | summarize LastCounters = max(TimeGenerated) by Node;
let recent = perf
    | join kind=inner last_perf on Node
    | where TimeGenerated > LastCounters - 5m
    | summarize
        CpuPct = round(avgif(CounterValue, ObjectName == "Processor" and CounterName == "% Processor Time" and InstanceName == "total"), 1),
        MemPct = round(avgif(CounterValue, ObjectName == "Memory" and CounterName == "% Used Memory"), 1),
        RootFreePct = round(minif(CounterValue, ObjectName == "Logical Disk" and CounterName == "% Free Space" and InstanceName == "/"), 1)
        by Node, LastCounters;
beats
| join kind=leftouter recent on Node
| extend MinutesSince = round((now() - LastHeartbeat) / 1m, 1)
| extend Status = iff(MinutesSince > 5, "silent", "ok")
| project Node, Status, LastHeartbeat, MinutesSince, LastCounters, CpuPct, MemPct, RootFreePct, Agent
| order by Node asc

let machines = "/providers/microsoft.hybridcompute/machines/";
let node_of = (id: string) { tolower(extract(@"(?i)/machines/([^/]+)$", 1, id)) };
let perf = union isfuzzy=true
    (Perf
    | where _ResourceId has machines
    | project TimeGenerated, Node = node_of(_ResourceId), ObjectName, CounterName, InstanceName, CounterValue),
    (datatable(TimeGenerated: datetime, Node: string, ObjectName: string, CounterName: string, InstanceName: string,
        CounterValue: real)[])
    | where Node in ({Nodes});
// Mounted file systems, not the total or the kernel's and boot mounts
// (/run, /dev, /sys, /boot).
perf
| where ObjectName == "Logical Disk" and CounterName == "% Free Space"
| where InstanceName != "total" and not(InstanceName has_any ("/run", "/dev", "/sys", "/boot"))
| summarize FreePct = round(min(CounterValue), 1) by bin(TimeGenerated, {TimeRange:grain}), Series = strcat(Node, " ", InstanceName)
| order by TimeGenerated asc

// Minutes in heartbeat gaps over 5 minutes, per node and time bin.
let range_start = todatetime('{TimeRange:start}');
let range_end = min_of(todatetime('{TimeRange:end}'), now());
let machines = "/providers/microsoft.hybridcompute/machines/";
let node_of = (id: string) { tolower(extract(@"(?i)/machines/([^/]+)$", 1, id)) };
let selected = print Node = dynamic([{Nodes}]) | mv-expand Node to typeof(string);
let beats = union isfuzzy=true
    (Heartbeat | where _ResourceId has machines | project TimeGenerated, Node = node_of(_ResourceId)),
    (datatable(TimeGenerated: datetime, Node: string)[])
    | where Node in ({Nodes});
// The range's start and end as sentinel beats, so the gaps before a node's
// first beat and after its last one count too.
selected
| mv-expand TimeGenerated = pack_array(range_start, range_end) to typeof(datetime)
| extend Sentinel = true
| union (beats | extend Sentinel = false)
| order by Node asc, TimeGenerated asc
| extend Prev = prev(TimeGenerated), PrevNode = prev(Node), PrevSentinel = prev(Sentinel)
| where Node == PrevNode and TimeGenerated - Prev > 5m
| project Node, GapStart = Prev, GapEnd = iff(Sentinel, datetime(null), TimeGenerated),
    Minutes = round((TimeGenerated - Prev) / 1m, 1),
    Note = case(Sentinel and PrevSentinel, "no heartbeat in the range",
        Sentinel, "still open at the end of the range",
        PrevSentinel, "before the first heartbeat in the range", "")
| extend GapEnd = coalesce(GapEnd, range_end)
// Each Minute ends a minute of the gap: bin it by the minute's start, so a
// gap ending on a bin boundary adds nothing to the next bin.
| mv-expand Minute = range(bin(GapStart, 1m) + 1m, GapEnd, 1m) to typeof(datetime)
| summarize GapMinutes = count() by Node, TimeGenerated = bin(Minute - 1m, {TimeRange:grain})
| union (selected | extend TimeGenerated = bin(range_start, {TimeRange:grain}), GapMinutes = 0)
| make-series GapMinutes = sum(GapMinutes) default = 0 on TimeGenerated from bin(range_start, {TimeRange:grain}) to range_end step {TimeRange:grain} by Node

// Gaps over 5 minutes between a node's heartbeats (one a minute), and a
// gap still open at the end of the range. A node with no heartbeat in the
// whole range shows one gap the length of the range.
let range_start = todatetime('{TimeRange:start}');
let range_end = min_of(todatetime('{TimeRange:end}'), now());
let machines = "/providers/microsoft.hybridcompute/machines/";
let node_of = (id: string) { tolower(extract(@"(?i)/machines/([^/]+)$", 1, id)) };
let selected = print Node = dynamic([{Nodes}]) | mv-expand Node to typeof(string);
let beats = union isfuzzy=true
    (Heartbeat | where _ResourceId has machines | project TimeGenerated, Node = node_of(_ResourceId)),
    (datatable(TimeGenerated: datetime, Node: string)[])
    | where Node in ({Nodes});
// The range's start and end as sentinel beats, so the gaps before a node's
// first beat and after its last one count too.
selected
| mv-expand TimeGenerated = pack_array(range_start, range_end) to typeof(datetime)
| extend Sentinel = true
| union (beats | extend Sentinel = false)
| order by Node asc, TimeGenerated asc
| extend Prev = prev(TimeGenerated), PrevNode = prev(Node), PrevSentinel = prev(Sentinel)
| where Node == PrevNode and TimeGenerated - Prev > 5m
| project Node, GapStart = Prev, GapEnd = iff(Sentinel, datetime(null), TimeGenerated),
    Minutes = round((TimeGenerated - Prev) / 1m, 1),
    Note = case(Sentinel and PrevSentinel, "no heartbeat in the range",
        Sentinel, "still open at the end of the range",
        PrevSentinel, "before the first heartbeat in the range", "")
| order by GapStart desc

// The worker's page counters per hour (AppMetrics, cloud role
// usnm-ocr-worker, role instance the node's name). Each row holds the
// count since the exporter's last one, in Sum. Empty until the worker
// sends telemetry.
union isfuzzy=true
    (AppMetrics
    | where AppRoleName == "usnm-ocr-worker" and Name in ("ocr.pages_done", "ocr.pages_failed", "ocr.pages_abandoned")
    | project TimeGenerated, AppRoleInstance, Name, Sum),
    (datatable(TimeGenerated: datetime, AppRoleInstance: string, Name: string, Sum: real)[])
| extend Node = tolower(AppRoleInstance)
| where Node in ({Nodes})
| summarize Pages = sum(Sum) by bin(TimeGenerated, 1h), Series = strcat(Node, " ", trim_start(@"ocr\.pages_", Name))
| order by TimeGenerated asc

// Billed MB a day the nodes' workspace took in (Usage), against its daily
// cap. Everything in the workspace counts: the agent's Syslog and Perf, the
// worker's Application Insights telemetry and the exchange account's queue
// logs. Days are UTC; the cap resets at a time of day of its own, so a day
// here can straddle two cap periods. Usage lags ingestion by up to a few
// hours.
// The cap is ocrNodeDailyCapGb in infra/main.bicep, which
// provisioning fills in here (cap_gb in ops/queries/ocr-node-health.kql
// has the same figure).
let cap_mb = todouble("__CAP_GB__") * 1000;
union isfuzzy=true
    (Usage | where IsBillable | project TimeGenerated, Quantity),
    (datatable(TimeGenerated: datetime, Quantity: real)[])
| summarize MB = round(sum(Quantity), 2) by Day = startofday(TimeGenerated)
| extend CapMB = cap_mb
| order by Day asc
